-- Every function that compares or searches values of the string family follows `equals`: values compare as if the
-- shorter one were padded with zero bytes whenever a `FixedString` is involved, and byte for byte between two `String`s.
-- Each line is the rows a function matches for a needle and whether they are the rows `equals` matches.

DROP TABLE IF EXISTS tab_string;
DROP TABLE IF EXISTS tab_fixed_string;

CREATE TABLE tab_string (id UInt32, s String, a Array(String), lc Array(LowCardinality(String)), m Map(String, UInt8), mv Map(UInt8, String)) ENGINE = Memory;
INSERT INTO tab_string SELECT number + 1, v, [v], [v], map(v, 1), map(1, v) FROM (SELECT number, ['ab', 'ab\0', 'ab\0\0', 'ab\0\0\0\0', 'zz'][number + 1] AS v FROM numbers(5));

CREATE TABLE tab_fixed_string (id UInt32, f FixedString(4), af Array(FixedString(4)), lcf Array(LowCardinality(FixedString(4))), mf Map(FixedString(4), UInt8), mvf Map(UInt8, FixedString(4))) ENGINE = Memory;
INSERT INTO tab_fixed_string SELECT number + 1, v, [v], [v], map(v, 1), map(1, v) FROM (SELECT number, ['ab', 'zz'][number + 1] AS v FROM numbers(2));

