SELECT 'has([toFixedString(\'ab\', 4)], \'ab\')', has([toFixedString('ab', 4)], 'ab');
SELECT 'has([toFixedString(\'ab\', 4)], \'ab\\0\')', has([toFixedString('ab', 4)], 'ab\0');
